<?php

namespace Database\Seeders;

/** Seeds `faq_categories` from database/seeders/data/faq_categories.json (generated by scripts/export-seed-data.ts in the frontend repo). */
class FaqCategoriesSeeder extends ContentSeederBase
{
    public const TABLE = 'faq_categories';

    public function run(): void
    {
        if (! $this->tableReady(self::TABLE)) {
            return;
        }
        $images = [];
        $keyCol = $this->hasColumn(self::TABLE, 'slug') ? 'slug' : 'name_ar';

        foreach ($this->json('faq_categories') as $row) {
            if (empty($row[$keyCol])) {
                continue;
            }
            $this->upsertFillEmpty(self::TABLE, [$keyCol => $row[$keyCol]], $row, $images);
        }

        $this->report(self::TABLE);
    }
}
